def test_dashboard_format_helpers_hide_raw_missing_values():
    assert dashboard.format_missing(None) == "Not available"
    assert dashboard.format_missing(float("nan")) == "Not available"
    assert dashboard.format_percent(None) == "Not enough history"
    assert dashboard.format_date_short("2026-03-14T00:00:00") == "2026-03-14"
    assert "nan" not in dashboard.score_badge(None).lower()
    cleaned = dashboard.clean_display_frame(pd.DataFrame({"Ready": [True, False]}))
    assert cleaned.iloc[0]["Ready"] == "Yes"
    assert cleaned.iloc[1]["Ready"] == "No"
    assert dashboard.public_status_label("insufficient_data") == "Insufficient data"
    assert dashboard.public_status_label("peer_data_unavailable") == "Peer data unavailable"
    assert dashboard.public_status_label("monitor_context") == "Monitor context"
    assert dashboard.public_status_label("not_ready") == "Not ready"
    assert dashboard.public_status_label("Broken") == "Thesis Review Needed"
    assert dashboard.public_status_label("Avoid") == "No Setup"
    assert dashboard.public_dataset_name("analyst_estimates") == "analyst estimates"
    assert dashboard.public_dataset_name("custom_universe") == "custom universe"
    assert dashboard.public_dataset_name("smh_holdings") == "SMH holdings"
    assert dashboard.public_dataset_name("prices") == "prices"

    action_rows = dashboard.clean_display_frame(
        pd.DataFrame(
            {
                "recommended_action": [
                    "Run make imports-validate, then make imports-preview, then make imports-apply, then make status to confirm the live local fundamentals."
                ]
            }
        )
    )
    assert "make status-check TOP_N=5" in action_rows.iloc[0]["Recommended Action"]

    card_html = dashboard.signal_card_html(
        "staged flow",
        "Review peer import draft",
        "Peer import draft ready; run make status before trusting peer mapping import drafts.",
        ["staged flow"],
        "make imports-preview",
    )
    assert "Review peer import file" in card_html
    assert "peer import file ready" in card_html.lower()
    assert "Review peer import draft" not in card_html
    assert "Peer import draft ready" not in card_html
    assert "make status-check TOP_N=5" in card_html
    assert "import file flow" in card_html
    assert "import draft flow" not in card_html
    assert "staged peer" not in card_html.lower()

    visitor_card_html = dashboard.signal_card_html(
        "visitor",
        "Read the summary first",
        "Command details stay available in the copyable commands section.",
        ["plain English"],
        "make dashboard-smoke",
        show_command=False,
    )
    assert "Read the summary first" in visitor_card_html
    assert "plain English" in visitor_card_html
    assert "make dashboard-smoke" not in visitor_card_html
    assert "command-chip" not in visitor_card_html

    public_card_html = dashboard.signal_card_html(
        "next review",
        "Best next review step",
        "Copy the next command only when you want to inspect or prove that local lane.",
        ["copy-only", "data-gated"],
        "make focus-peers TICKER=NVDA",
        show_command=False,
    )
    assert "make focus-peers" not in public_card_html
    assert "copy-only" not in public_card_html
    assert "copy the next command" not in public_card_html.lower()
    assert "read-only" in public_card_html
    assert "Open proof details" in public_card_html

    queue_card_html = dashboard.signal_card_html(
        "latest proof",
        "Peer valuation: still_blocked",
        "Proof command: make readiness && make peer-mapping-queue TOP_N=25. Impact: 3273 coverage rows. Guardrail: This rank is an operations queue, not a security recommendation or evidence that data is already available. Peer sub-states: peer_price=9; peer_valuation_inputs=0. Top blocker: benchmark_relative_return. Next check: make focus-price TICKER=NVDA.",
        ["dry_run_first", "missing_before"],
        "make readiness",
        show_command=False,
        queue_preview=True,
    )
    assert "Proof command" not in queue_card_html
    assert "make readiness" not in queue_card_html
    assert "still blocked" in queue_card_html
    assert "peer price" in queue_card_html
    assert "peer valuation inputs" in queue_card_html
    assert "benchmark-relative return" in queue_card_html
    assert "open the evidence drawer" in queue_card_html
    assert "Impact: 3,273" in queue_card_html
    assert "operations queue only" in queue_card_html
    assert "This rank is an operations queue" not in queue_card_html
    assert "Dry-run first" in queue_card_html
    assert "missing before" in queue_card_html
    assert "still_blocked" not in queue_card_html
    assert "peer_valuation_inputs" not in queue_card_html
    assert "benchmark_relative_return" not in queue_card_html
    assert "make focus-price" not in queue_card_html

    rendered_batches: list[list[dict[str, object]]] = []
    original_render_signal_cards = dashboard.render_signal_cards

    def capture_render(cards, *, show_commands=True, variant=""):
        rendered_batches.append(list(cards))

    dashboard.render_signal_cards = capture_render
    try:
        dashboard.render_operator_queue_preview(
            [{"title": f"Card {index}"} for index in range(6)],
            limit=4,
        )
    finally:
        dashboard.render_signal_cards = original_render_signal_cards
    assert len(rendered_batches) == 1
    assert [card["title"] for card in rendered_batches[0]] == ["Card 0", "Card 1", "Card 2", "Card 3"]

    workflow_rows = dashboard.clean_display_frame(
        pd.DataFrame(
            {
                "workflow_group": ["dcf_ready_peer_mapping"],
                "workflow_scope": ["active_universe"],
                "peer_blocker_type": ["missing_peer_mapping"],
                "peer_valuation_status": ["peer_valuation_blocked"],
                "mapping_status": ["insufficient_mapping"],
                "valuation_status": ["not_ready"],
                "peer_relative_status": ["peer_data_unavailable"],
            }
        )
    )
    rendered = " ".join(workflow_rows.astype(str).stack().tolist()).lower()
    rendered_columns = " ".join(workflow_rows.columns).lower()
    assert "dcf-ready peer mapping" in rendered
    assert "active universe" in rendered
    assert "missing peer mapping" in rendered
    assert "peer valuation blocked" in rendered
    assert "insufficient mapping" in rendered
    assert "not ready" in rendered
    assert "peer data unavailable" in rendered
    assert "dcf_ready_peer_mapping" not in rendered
    assert "active_universe" not in rendered
    assert "missing_peer_mapping" not in rendered
    assert "peer_data_unavailable" not in rendered
    assert "not_ready" not in rendered
    assert "Unlock Path" in workflow_rows.columns
    assert "Queue Scope" in workflow_rows.columns
    assert "Peer Blocker Type" in workflow_rows.columns
    assert "workflow_group" not in rendered_columns
    assert "workflow_scope" not in rendered_columns


def test_data_health_auto_refresh_status_cards_read_cached_preflight(tmp_path: Path):
    outputs = tmp_path / "outputs"
    outputs.mkdir()
    (outputs / "session_source_preflight.json").write_text(
        json.dumps(
            {
                "source_activation": {"status": "not_required", "reason": "executable_source_available"},
                "source_categories": {
                    "free_public_available": ["stooq", "yahoo", "sec"],
                    "keyed_free_tier_available": [],
                    "optional_broker_disabled": ["ibkr"],
                    "paid_or_locked": ["fmp", "alpha_vantage", "finnhub"],
                },
                "source_activation_console_v2": {
                    "next_executable_lane": "coverage_workflow_evidence",
                    "next_executable_command": "make project-status",
                    "free_tier_batch_limits": {
                        "fmp": {"recommended_daily_request_limit": 250, "recommended_batch_size": 25},
                        "alpha_vantage": {"recommended_daily_request_limit": 25, "recommended_batch_size": 5},
                        "finnhub": {"recommended_daily_request_limit": 60, "recommended_batch_size": 10},
                    },
                    "operator_summary": {
                        "can_run_now": "coverage_workflow_evidence",
                        "needs_setup": "fmp, alpha_vantage, finnhub",
                        "avoid_repeating": "fundamentals_share_count_source_ladder",
                        "next_step": "make project-status",
                    },
                },
            }
        ),
        encoding="utf-8",
    )

    cards = dashboard.data_health_auto_refresh_status_cards(root=tmp_path, schedule="weekly")
    rendered = " ".join(str(value) for card in cards for value in card.values()).lower()

    assert [card["kicker"] for card in cards] == [
        "AUTO REFRESH STATUS",
        "SOURCE SETUP",
        "NEXT SCHEDULER STEP",
    ]
    assert cards[2]["title"] == "make readiness-preview TOP_N=20"
    assert cards[2]["command"] == "make readiness-preview TOP_N=20"
    assert "can run now: inspection_required" in rendered
    assert "needs setup: fmp, alpha vantage, finnhub" in rendered
    assert "avoid repeating: fundamentals/share-count source ladder" in rendered
    assert "coverage_workflow_evidence" not in rendered
    assert "fundamentals_share_count_source_ladder" not in rendered
    assert "generated csv/json/report churn stays excluded" in rendered


def test_data_health_source_activation_setup_cards_use_guide_without_secrets(monkeypatch):
    monkeypatch.setenv("FMP_API_KEY", "secret-fmp-key")
    monkeypatch.delenv("ALPHA_VANTAGE_API_KEY", raising=False)
    monkeypatch.delenv("FINNHUB_API_KEY", raising=False)
    monkeypatch.delenv("IBKR_HOST", raising=False)
    monkeypatch.delenv("IBKR_PORT", raising=False)
    monkeypatch.delenv("IBKR_CLIENT_ID", raising=False)

    cards = dashboard.data_health_source_activation_setup_cards()
    rendered = " ".join(str(value) for card in cards for value in card.values()).lower()

    assert [card["kicker"] for card in cards] == [
        "ACTIVATION PLAN",
        "FREE PUBLIC SOURCES",
        "KEYED FREE-TIER SETUP",
        "BROKER DATA BOUNDARY",
        "APPLY GATE",
    ]
    assert "run make project-status-check first" in rendered
    assert "reviewed one-ticker smoke command only" in rendered
    assert "sec companyfacts" in rendered
    assert "fmp free tier" in rendered
    assert "keyed_free_tier_available" in rendered
    assert "secret-fmp-key" not in rendered
    assert "ibkr read-only stays disabled" in rendered
    assert "make imports-preview import_tickers=<ticker>" in rendered


