def test_data_health_page_header_frames_unlock_workflow_not_diagnostics():
    source = Path("src/dashboard.py").read_text(encoding="utf-8")

    function_index = source.index("def render_data_health(")
    provider_none_index = source.index("if provider is None:", function_index)
    validation_load_index = source.index("validation_rows = pd.DataFrame(provider.get_local_data_validation())", provider_none_index)
    public_header_index = source.index("if public_mode:", validation_load_index)
    coverage_summary_index = source.index("render_data_health_coverage_summary(readiness_summary, peer_readiness_frame, public_mode=True)", validation_load_index)
    proof_map_index = source.index("data_health_public_proof_map_cards(readiness_summary, readiness_freshness)", coverage_summary_index)
    assert provider_none_index < validation_load_index < public_header_index < coverage_summary_index < proof_map_index
    assert source.index("render_data_health_coverage_summary(readiness_summary, peer_readiness_frame, public_mode=True)", public_header_index) < source.index(
        'render_section_header("Proof Map"', public_header_index
    )
    assert "if public_mode and project_status_payload is None:" in source
    refresh_note_index = source.index('st.expander("Refresh status note"')
    quick_read_index = source.index('render_section_header("Data Health Quick Read"')
    assert refresh_note_index < quick_read_index
    assert 'st.expander("Refresh status note", expanded=False)' in source
    assert 'public_evidence_drawer_expanded = selected_drawer == "proof"' in source
    assert 'st.expander("Public evidence drawer", expanded=public_evidence_drawer_expanded)' in source
    assert "One clear answer per lane before selected-lane operations" in source
    assert "Data Health Quick Read" in source
    assert "Which proof path should you inspect first, before opening detailed sections." in source
    assert "Diagnostic triage only; use this after the lane answer when a reviewer asks what evidence to inspect first." in source
    assert "No active-universe unlock rows are available. Refresh readiness and confirm the active-universe scope." in source
    assert "No active-universe unlock rows are available. Run make readiness" not in source
    assert "before opening detailed tables" not in source
    assert "deeper Data Health details" not in source
    assert "missing_optional_labels = [public_dataset_name(name) for name in missing_optional]" in source
    assert 'validation_rows["name"] = validation_rows["name"].map(public_dataset_name)' in source
    assert 'st.expander("Local dataset checks", expanded=False)' in source
    assert 'st.expander("Local dataset validation details", expanded=False)' not in source
    assert "Supported Analysis Ladder" in source
    assert "Freshness Routine" in source
    assert "How to keep data current without daily manual full-universe refreshes." in source
    assert "render_signal_cards(data_health_freshness_routine_cards(readiness_summary), show_commands=False)" in source
    assert "Valuation Proof Snapshot" in source
    assert "Plain-English valuation worklists before the broader market-wide tables." in source
    assert "Plain-English valuation queues before the full command center details." not in source
    assert "When Is A Stock Ready Enough?" not in source
    assert "Validation, source availability, price refresh diagnostics, and onboarding actions in one place." not in source


