def test_single_stock_report_intro_cards_explain_output_before_generation():
    cards = dashboard.single_stock_report_intro_cards()
    summary_cards = dashboard.single_stock_report_intro_summary_cards()
    demo_cards = dashboard.single_stock_demo_ticker_cards()
    demo_picker_cards = dashboard.single_stock_demo_picker_cards()
    rendered = " ".join(str(value) for card in cards for value in card.values()).lower()
    summary_rendered = " ".join(str(value) for card in summary_cards for value in card.values()).lower()
    demo_rendered = " ".join(str(value) for card in demo_cards for value in card.values()).lower()
    demo_picker_rendered = " ".join(str(value) for card in demo_picker_cards for value in card.values()).lower()

    assert [card["kicker"] for card in cards] == [
        "WHAT THIS MEANS",
        "WHAT YOU CAN ANALYZE NOW",
        "WHAT IS STILL LOCKED",
        "OUTPUT BOUNDARY",
        "COPY NEXT",
    ]
    assert "ready, blocked, or excluded first" in rendered
    assert "inputs are separated from calculations" in rendered
    assert "local/provider rows supply prices and fundamentals" in rendered
    assert "runs dcf math when inputs are complete" in rendered
    assert "peer comparison, earnings, and analyst-estimate context stay locked" in rendered
    assert "company valuation is excluded for etf/index/fund monitor rows" in rendered
    assert "etf/index/fund dcf is excluded" not in rendered
    assert "no hidden final call" in rendered
    assert "source inputs, product calculations, blocked sections" in rendered
    assert "does not convert partial data into a portfolio action" in rendered
    assert "start with a demo or one selected ticker" in rendered
    assert "for a visitor demo, use one example ticker" in rendered
    assert "open the review, then read the selected ticker state and what can be read now before opening detailed review tabs" in rendered
    assert len(summary_cards) == 1
    assert summary_cards[0]["kicker"] == "ONE-TICKER REVIEW"
    assert "open one ticker review" in summary_rendered
    assert "select a ticker, open the read-only review, then read what can be read now first" in summary_rendered
    assert "locked inputs" in summary_rendered
    assert "excluded company valuation" in summary_rendered
    assert "next proof step" in summary_rendered
    assert "copy-only local step" not in summary_rendered
