def test_single_stock_page_keeps_full_intro_collapsed_and_uses_open_state():
    source = Path("src/dashboard.py").read_text(encoding="utf-8")
    render_index = source.index("def render_single_stock_report(")

    provider_ticker_load_index = source.index("local_tickers = provider.list_local_tickers()", render_index)
    contract_cards_index = source.index("render_signal_cards(pre_report_cards", provider_ticker_load_index)
    auto_open_index = source.index("if query_open_review and not report_payload:", contract_cards_index)
    opening_note_index = source.index('"Opening saved review evidence."', auto_open_index)
    review_open_note_index = source.index('"Review is open."', auto_open_index)
    preview_note_index = source.index('"What happens next."', review_open_note_index)
    build_button_index = source.index('st.button("Open Review"', preview_note_index)
    readable_now_index = source.index("What can be read now", review_open_note_index)
    evidence_index = source.index('st.expander("Ticker Readiness Evidence", expanded=False)', build_button_index)
    loop_index = source.index("render_research_loop_strip(**single_stock_research_loop_context(ticker, report_payload))")
    state_expander_index = source.index('st.expander("Advanced: example report states", expanded=False)')
    summary_index = source.index("render_signal_cards(single_stock_report_intro_summary_cards(), show_commands=show_card_commands)", state_expander_index)
    note_index = source.index("demo_note_title, demo_note_body = single_stock_demo_picker_note()", state_expander_index)
    demo_index = source.index("render_signal_cards(single_stock_demo_picker_cards(), show_commands=show_card_commands)", state_expander_index)
    expander_index = source.index('st.expander("Advanced: how single-stock reports work"', state_expander_index)
    full_intro_index = source.index("render_signal_cards(single_stock_report_intro_cards(), show_commands=show_card_commands)", state_expander_index)

    assert provider_ticker_load_index < contract_cards_index < auto_open_index < opening_note_index
    assert auto_open_index < review_open_note_index < preview_note_index < build_button_index < evidence_index < loop_index < state_expander_index
    assert review_open_note_index < readable_now_index < evidence_index
    assert state_expander_index < summary_index < note_index < demo_index < expander_index < full_intro_index
    assert 'st.expander("Advanced: example report states", expanded=False)' in source
    assert 'st.expander("Advanced: how single-stock reports work", expanded=False)' in source
    assert 'st.expander("Ticker Readiness Evidence", expanded=False)' in source
    assert 'st.expander("Evidence row details", expanded=False)' in source
    assert 'st.expander("Ticker coverage and peer context"' not in source
    assert 'st.expander("Complete local coverage details"' not in source
    assert 'metric("Peer File"' in source
    assert 'metric("Peer Dataset"' not in source
    assert "Preview action." not in source
    assert "It does not refresh prices, import files, or contact external accounts." in source


