def test_data_health_coverage_summary_includes_cached_source_activation_context(tmp_path):
    root = tmp_path
    outputs_dir = root / "outputs"
    outputs_dir.mkdir()
    (outputs_dir / "session_source_preflight.json").write_text(
        json.dumps(
            {
                "source_activation_console_v2": {
                    "next_executable_lane": "sec_fundamentals_share_count",
                    "free_public_available": ["sec", "sec_submissions", "yfinance_stage", "stooq"],
                    "keyed_free_tier_available": [],
                    "missing_keyed_free_tier": ["fmp", "alpha_vantage", "finnhub"],
                    "optional_broker_disabled": ["ibkr"],
                    "source_path_last_tried": {
                        "sec": "ok",
                        "yfinance_fundamentals": "probe_succeeded",
                        "fmp": "provider_key_missing",
                    },
                    "do_not_retry_this_session": ["fmp"],
                    "setup_commands": {
                        "fmp": "export FMP_API_KEY='<key>'",
                        "stooq": "no key required for public daily OHLCV",
                    },
                    "free_tier_batch_limits": {
                        "fmp": {"recommended_daily_request_limit": 250, "recommended_batch_size": 25},
                        "alpha_vantage": {"recommended_daily_request_limit": 25, "recommended_batch_size": 5},
                        "finnhub": {"recommended_daily_request_limit": 60, "recommended_batch_size": 10},
                    },
                }
            }
        ),
        encoding="utf-8",
    )
    summary = {
        "master_universe": 100,
        "price_ready": 99,
        "fundamentals_ready": 12,
        "dcf_ready": 9,
        "peer_ready": 4,
    }

    frame = dashboard.data_health_coverage_summary_frame(summary, root=root)
    cards = dashboard.data_health_coverage_summary_cards(summary, root=root)
    rendered = " ".join(str(value) for card in cards for value in card.values()).lower()

    assert "Source activation" in set(frame["lane"])
    source_row = frame.loc[frame["lane"].eq("Source activation")].iloc[0]
    assert source_row["state"] == "supported"
    assert source_row["coverage_tier"] == "source_activation_context"
    assert "sec_fundamentals_share_count" in source_row["one_clear_answer"]
    assert "sec, sec_submissions, yfinance_stage, stooq" in source_row["supporting_coverage"]
    assert "fmp, alpha_vantage, finnhub" in source_row["blocked_or_limited"]
    assert "ibkr disabled unless explicitly configured" in source_row["why_blocked_or_limited"].lower()
    assert "Configure FMP_API_KEY locally" in source_row["proof_to_unlock"]
    assert "one-ticker validate/preview smoke before any apply" in source_row["proof_to_unlock"]
    assert "last tried: sec=ok" in source_row["stop_rule"].lower()
    assert "do not retry this session: fmp" in source_row["stop_rule"].lower()
    assert "free-tier limits: fmp<=250/day and <=25/run" in source_row["stop_rule"].lower()
    assert "alpha_vantage<=25/day and <=5/run" in source_row["stop_rule"].lower()
    assert "finnhub<=60/day and <=10/run" in source_row["stop_rule"].lower()
    rendered_source_row = " ".join(str(value) for value in source_row.to_dict().values()).lower()
    assert "source availability categories only" in rendered_source_row
    assert "not readiness proof" in rendered_source_row
    assert "free public paths can be executable without keys" in rendered_source_row
    assert "keyed free-tier paths require local keys and small-batch limits" in rendered_source_row
    assert "optional read-only broker path stays disabled unless explicitly configured" in rendered_source_row
    assert "validate/preview/apply" in rendered_source_row
    assert "cached session source preflight" in rendered
    assert "configure fmp_api_key locally" in source_row["proof_to_unlock"].lower()
    assert "free-tier limits" in source_row["stop_rule"].lower()
    assert "do not retry this session: fmp" in source_row["stop_rule"].lower()
    assert "buy" not in rendered
    assert "sell" not in rendered
    assert "order routing" not in rendered


