def test_data_health_coverage_summary_renders_before_public_and_operator_details():
    source = Path("src/dashboard.py").read_text(encoding="utf-8")

    function_index = source.index("def render_data_health(")
    provider_none_index = source.index("if provider is None:", function_index)
    public_intro_chunk = source[function_index:provider_none_index]
    assert 'render_section_header(\n            "Data Health"' not in public_intro_chunk
    public_index = source.index("if public_mode:", provider_none_index)
    public_coverage_index = source.index(
        "render_data_health_coverage_summary(readiness_summary, peer_readiness_frame, public_mode=True)",
        public_index,
    )
    first_30_index = source.index("data_health_public_first_30_second_cards(readiness_summary)", public_coverage_index)
    guidance_expander_index = source.index('st.expander("Advanced: how readiness works", expanded=False)', public_coverage_index)
    visitor_paths_index = source.index('render_section_header("Public path options"', first_30_index)
    public_lead_in_chunk = source[public_index:guidance_expander_index]
    assert '"Data Quality / Readiness"' not in public_lead_in_chunk
    public_return_index = source.index("return", source.index("Operator details are hidden."))
    operator_coverage_index = source.index(
        "render_data_health_coverage_summary(readiness_summary, peer_readiness_frame)",
        public_return_index,
    )
    operator_coverage_expander_index = source.index(
        'st.expander("Advanced: coverage and workflow details", expanded=False)',
        public_return_index,
    )
    ops_index = source.index("render_data_health_operator_hero(operator_snapshot_cards)", operator_coverage_index)

    assert public_index < public_coverage_index < guidance_expander_index < first_30_index < visitor_paths_index
    assert public_return_index < operator_coverage_expander_index < operator_coverage_index < ops_index
    assert '"Selected Lane Answer"' in source
    assert '"Coverage Summary / What Can I Use?"' in source
    assert "One clear answer per lane before selected-lane operations" in source
    assert 'st.expander("Advanced: coverage lane details", expanded=False)' in source
    source_details_index = source.index('st.expander("Advanced: operator source setup details", expanded=False)', ops_index)
    auto_refresh_index = source.index('render_section_header(\n            "Auto Refresh Status"', source_details_index)
    source_setup_index = source.index('render_section_header(\n            "Source Setup Guide"', auto_refresh_index)
    source_guidance_index = source.index('render_section_header(\n            "Source Readiness Guidance"', source_setup_index)
    next_action_index = source.index('st.expander("Advanced: operator next-action details", expanded=False)', source_guidance_index)

    assert ops_index < source_details_index < auto_refresh_index < source_setup_index < source_guidance_index < next_action_index
    assert 'st.expander("Source setup and refresh details", expanded=False)' not in source
    assert 'st.expander("Secondary operator next-action detail", expanded=False)' not in source
    assert "show_commands=False" in source[
        source.index("def render_data_health_coverage_summary(") : source.index("def _trusted_ready_count(")
    ]


