def test_data_health_public_mode_has_loading_placeholder_before_table_loads():
    source = Path("src/dashboard.py").read_text(encoding="utf-8")

    function_index = source.index("def render_data_health(")
    provider_none_index = source.index("if provider is None:", function_index)
    placeholder_index = source.index("public_loading_placeholder = st.empty()", provider_none_index)
    placeholder_copy_index = source.index('"Lane answer / coverage summary guide"', placeholder_index)
    placeholder_answer_index = source.index("Use the lane cards before opening advanced proof details", placeholder_copy_index)
    placeholder_contract_index = source.index(
        "Raw tables, route maps, queues, proof ledgers, and commands stay closed",
        placeholder_answer_index,
    )
    placeholder_stop_index = source.index("tone=\"success\"", placeholder_contract_index)
    validation_load_index = source.index("validation_rows = pd.DataFrame(provider.get_local_data_validation())", placeholder_index)
    clear_placeholder_index = source.index("public_loading_placeholder.empty()", validation_load_index)
    coverage_summary_index = source.index(
        "render_data_health_coverage_summary(readiness_summary, peer_readiness_frame, public_mode=True)",
        clear_placeholder_index,
    )
    coverage_summary_function_index = source.index("def render_data_health_coverage_summary(")
    coverage_summary_title_index = source.index('"Coverage Summary / What Can I Use?"', coverage_summary_function_index)
    coverage_summary_copy_index = source.index(
        "One clear answer per lane before selected-lane operations",
        coverage_summary_title_index,
    )
    selected_lane_answer_index = source.index('"Selected Lane Answer"', coverage_summary_copy_index)

    assert (
        provider_none_index
        < placeholder_index
        < placeholder_copy_index
        < placeholder_contract_index
        < placeholder_stop_index
        < validation_load_index
    )
    assert validation_load_index < clear_placeholder_index < coverage_summary_index
    assert coverage_summary_function_index < coverage_summary_title_index < coverage_summary_copy_index
    assert coverage_summary_copy_index < selected_lane_answer_index


