def test_data_health_source_readiness_guidance_renders_before_operator_next_action():
    source = Path("src/dashboard.py").read_text(encoding="utf-8")

    public_return_index = source.index("        return\n    selected_lane = DATA_HEALTH_OPERATOR_LANES[selected_lane_key]")
    lane_answer_index = source.index('render_section_header(\n        "Selected Lane Answer"', public_return_index)
    lane_answer_cards_index = source.index("data_health_selected_lane_answer_cards(", lane_answer_index)
    source_gate_action_index = source.index("source_gate_next_action = data_health_source_gate_next_action(", lane_answer_cards_index)
    research_loop_index = source.index("render_research_loop_strip(", source_gate_action_index)
    research_loop_next_action_index = source.index("next_action=data_health_current_mode_next_action(", research_loop_index)
    research_loop_source_gate_index = source.index("source_gate_next_action=source_gate_next_action", research_loop_next_action_index)
    mode_strip_index = source.index("render_data_health_current_mode_strip(", public_return_index)
    mode_strip_source_gate_index = source.index("source_gate_next_action=source_gate_next_action", mode_strip_index)
    source_details_index = source.index('st.expander("Advanced: operator source setup details", expanded=False)', mode_strip_index)
    source_pivot_index = source.index('"Source-Proof Pivot"', source_details_index)
    source_pivot_cards_index = source.index("render_signal_cards(source_exhaustion_pivot_cards", source_pivot_index)
    guidance_header_index = source.index('render_section_header(\n            "Source Readiness Guidance"', source_details_index)
    guidance_cards_index = source.index("data_health_source_readiness_guidance_cards(", guidance_header_index)
    next_action_index = source.index('st.expander("Advanced: operator next-action details", expanded=False)', guidance_cards_index)

    assert lane_answer_index < lane_answer_cards_index < source_gate_action_index < research_loop_index
    assert research_loop_index < research_loop_next_action_index < research_loop_source_gate_index < mode_strip_index
    assert mode_strip_index < mode_strip_source_gate_index < source_details_index
    assert source_details_index < source_pivot_index < source_pivot_cards_index < guidance_header_index
    assert source_details_index < guidance_header_index < guidance_cards_index < next_action_index
    assert 'st.expander("Source setup and refresh details", expanded=False)' not in source
    assert 'st.expander("Secondary operator next-action detail", expanded=False)' not in source
    assert "One plain-language answer for the selected lane before provider setup, pilot gates, or advanced proof evidence." in source
    assert "One plain-language answer for the selected lane before provider setup, pilot gates, or raw proof tables." not in source
    assert "what setup could change the gate, what should not be retried, and the review boundary before provider details" in source
    assert "what setup could change the gate, what should not be retried, and the one safe smoke before provider details" not in source
    assert "Check freshness, source queues, rejected rows, and generated-artifact hygiene before interpreting counts." in source


def test_data_health_secondary_operator_action_is_collapsed_after_lane_answer():
    source = Path("src/dashboard.py").read_text(encoding="utf-8")

    public_return_index = source.index("        return\n    selected_lane = DATA_HEALTH_OPERATOR_LANES[selected_lane_key]")
