def test_data_health_additional_operator_evidence_hides_summary_commands_by_default():
    source = Path("src/dashboard.py").read_text(encoding="utf-8")
    additional_operator_index = source.index('st.expander("Last-resort diagnostic context", expanded=False)')
    drawer_source = source[additional_operator_index : source.index("if show_details:", additional_operator_index + 1)]
    ops_center_render_index = source.index(
        "render_signal_cards(data_health_readiness_ops_center_cards(ops_center), show_commands=False)",
        additional_operator_index,
    )
    coverage_frontier_render_index = source.index(
        "render_signal_cards(data_health_coverage_frontier_cards(coverage_frontier), show_commands=False)",
        ops_center_render_index,
    )
    command_bundle_render_index = source.index(
        "render_signal_cards(data_health_command_bundle_cards(command_bundles_frame), show_commands=False)",
        coverage_frontier_render_index,
    )
    runbook_render_index = source.index(
        "render_signal_cards(data_health_command_bundle_runbook_cards(command_bundle_runbook_frame), show_commands=False)",
        command_bundle_render_index,
    )
    readiness_render_index = source.index(
        "render_signal_cards(readiness_panel_cards(readiness_summary), show_commands=False)",
        runbook_render_index,
    )
    overview_cards_index = source.index(
        "data_health_overview_cards(validation_rows, price_status_frame, action_queue_frame, coverage_frame)",
        readiness_render_index,
    )
    overview_command_visibility_index = source.index("show_commands=False", overview_cards_index)

    assert (
        additional_operator_index
        < ops_center_render_index
        < coverage_frontier_render_index
        < command_bundle_render_index
        < runbook_render_index
        < readiness_render_index
        < overview_cards_index
        < overview_command_visibility_index
    )
    assert "Last-resort context only; not the primary workflow." in drawer_source
    assert "Use after Home, Stock Selector, Single-Stock Report, Data Health lane answer, and Proof History evidence." in drawer_source
    assert "Diagnostic triage only; use this after the lane answer when a reviewer asks what evidence to inspect first." in drawer_source
    assert "Optional diagnostic context for holdings-first coverage planning; not the default next-action workflow." in drawer_source
    assert "Optional diagnostic runbook; use only after source gates or provider setup change the queue." in drawer_source
    assert "Diagnostic ticker-level coverage rows; inspect only after the summary cards answer the lane state." in drawer_source
    assert "Diagnostic guided coverage rows; copy-only context, not an apply path." in drawer_source
    assert "Compact diagnostic status only; not a source-proof unlock." in drawer_source
    assert "Diagnostic proof prompts only; they do not replace source gates, validation, preview, or Proof History evidence." in drawer_source


